def read_ints():
    return list(map(int, input().split()))

def is_eulerian_circuit_possible(n, m, trails):
    if m == 0:
        return 1
    degrees = [0] * (n + 1)
    for x, y in trails:
        degrees[x] += 1
        degrees[y] += 1

    odd_count = sum(1 for d in degrees if d % 2 == 1)
    if odd_count == 0:
        return 0
    return odd_count // 2

